-- Freelancer hakediş ödemeleri (yalnızca admin görür).
--
-- Elle verilen 161 ad + IBAN + tutar, 26.08.2026'da ödenmiş olarak kaydedilir.
-- Payout modeli sipariş+satıcıya zorunlu bağlı olduğundan bu dış ödemeler ayrı tabloda
-- tutulur. İsimler Türkçe kurallarıyla düzgün büyük/küçük harfe getirildi; IBAN'lar
-- boşluksuz saklanır. ON CONFLICT DO NOTHING ile idempotent.

CREATE TABLE IF NOT EXISTS "freelancer_payouts" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "iban" TEXT NOT NULL,
    "amount" DECIMAL(12,2) NOT NULL,
    "paidAt" TIMESTAMP(3) NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "freelancer_payouts_pkey" PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "freelancer_payouts_paidAt_idx" ON "freelancer_payouts"("paidAt");

ON CONFLICT ("id") DO NOTHING;
